import re, os, json, linecache, glob

# Load demonstrations from session
def load_demos():
    d = os.environ.get('RLM_SESSION_DIR', '')
    filepath = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    lines = open(filepath).read().split('\n')
    demos = {'demo_pairs': [], 'test_input': None}
    demo_counter = 0
    test_seen = False
    for line in lines:
        line = line.strip(); 
        if not line:
            continue
        if line.startswith('Demo pair '):
            match = re.match(r'Demo pair (\d+) (input|output|text) \((\d+)x(\d+)\):\n(.*)', line, re.DOTALL)
            if match:
                demo_counter += 1
                kinds = match.group(1)
                is_input = kinds == 'input'
                rows = [[int(x) for x in match.group()[match.end():].split('\n')[0].split()] 
                        for _ in range(int(match.group(2)))]
                if match:
                    rows = []
                    content = line[match.end():].split('\n')
                    for r in content[:int(match.group(2))]:
                        rows.append([int(x) for x in r.split()])
                    print(f'Demo {demo_counter} {kinds}: {len(rows[0])} cols')
                    demos['demo_pairs'].append({'input': rows, 'output': rows})
        elif line.startswith('Test input'):
            test_seen = True
    match = re.search(r'is Test Input (\d+)x(\d+)\n(.*)', '\n'.join(lines))
    return demos, lines
demos, lines = load_demos()
